// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ActionExecution) predicate.ActionExecution {
	return predicate.ActionExecution(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ActionExecution) predicate.ActionExecution {
	return predicate.ActionExecution(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ActionExecution) predicate.ActionExecution {
	return predicate.ActionExecution(sql.NotPredicates(p))
}
